-- Synthetic course data only. Exported 2026-09-08 from the isolated demo.
-- Dates are fixed near 2026-09-07. Prefer Java DemoSeeder for fresh relative dates.
-- Run AFTER 00-create-database.sql and 01-schema.sql in a new dedicated empty database.
-- Do not combine with Java DemoSeeder. No sys_user/password hashes/audit records exported.
-- Bootstrap creates admin from APP_ADMIN_PASSWORD afterwards; create other roles in UI.
-- The temporary procedure fails if ANY business table is nonempty. No existing rows are deleted.
USE smart_care;
SET NAMES utf8mb4;
DELIMITER $$
CREATE PROCEDURE seed_smart_care_demo_v1()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  ROLLBACK;
  RESIGNAL;
 END;
 IF ((SELECT COUNT(*) FROM region) + (SELECT COUNT(*) FROM elder) + (SELECT COUNT(*) FROM doctor) + (SELECT COUNT(*) FROM health_rule) + (SELECT COUNT(*) FROM health_record) + (SELECT COUNT(*) FROM followup_plan) + (SELECT COUNT(*) FROM followup_record) + (SELECT COUNT(*) FROM watch_device) + (SELECT COUNT(*) FROM device_binding) + (SELECT COUNT(*) FROM location_point) + (SELECT COUNT(*) FROM geofence) + (SELECT COUNT(*) FROM geofence_member) + (SELECT COUNT(*) FROM geofence_alert) + (SELECT COUNT(*) FROM geofence_state)) <> 0 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Demo seed requires empty business tables';
 END IF;
 START TRANSACTION;

-- region

-- elder

-- doctor

-- health_rule

-- health_record

-- followup_plan

-- followup_record

-- watch_device

-- device_binding

-- location_point

-- geofence

-- geofence_member

-- geofence_alert

-- geofence_state
 COMMIT;
END$$
DELIMITER ;
CALL seed_smart_care_demo_v1();
DROP PROCEDURE seed_smart_care_demo_v1;
